function formatDate(value?: string) {
  if (!value) {
    return 'Unknown';
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }

  return date.toLocaleString([], {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

function normalizeLabel(value?: string | null) {
  if (!value || !value.trim()) {
    return 'Unspecified';
  }

  return value.trim();
}

function titleCase(value: string) {
  if (!value) {
    return value;
  }

  return value
    .split(/[\s_-]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function readMetadataValue(metadata: Record<string, unknown> | null | undefined, key: string) {
  const raw = metadata?.[key];
  return typeof raw === 'string' ? raw : '';
}

function countBy<T>(items: T[], getKey: (item: T) => string | undefined | null): RankedDatum[] {
  const bucket = new Map<string, number>();

  items.forEach((item) => {
    const key = normalizeLabel(getKey(item));
    bucket.set(key, (bucket.get(key) || 0) + 1);
  });

  return Array.from(bucket.entries())
    .map(([label, value]) => ({ label, value }))
    .sort((a, b) => b.value - a.value || a.label.localeCompare(b.label));
}

function extractYear(value?: string) {
  if (!value) {
    return null;
  }

  const match = value.match(/\d{4}/);
  if (!match) {
    return null;
  }

  const parsed = Number.parseInt(match[0], 10);
  return Number.isNaN(parsed) ? null : parsed;
}

function toDecadeLabel(year: number | null) {
  if (!year) {
    return 'Unknown';
  }

  const decade = Math.floor(year / 10) * 10;
  return `${decade}s`;
}

function getLocationLabel(item: CatalogItem) {
  const city = normalizeLabel(item.currentPhysicalLocation?.city || item.locationOfCreation?.city);
  const country = normalizeLabel(item.currentPhysicalLocation?.country || item.locationOfCreation?.country);

  if (city === 'Unspecified' && country === 'Unspecified') {
    return 'Unspecified';
  }

  if (city !== 'Unspecified' && country !== 'Unspecified') {
    return `${city}, ${country}`;
  }

  return city !== 'Unspecified' ? city : country;
}

function getLookupCity(item: CatalogItem) {
  const rawCity = normalizeLabel(
    item.currentPhysicalLocation?.city ||
      item.locationOfCreation?.city ||
      item.currentPhysicalLocation?.cityHistoricalName ||
      item.locationOfCreation?.cityHistoricalName
  );

  if (rawCity === 'Unspecified') {
    return rawCity;
  }

  const cityKey = rawCity
    .split(',')[0]
    .split('/')[0]
    .trim()
    .toLowerCase();

  const rawCountry = normalizeLabel(
    item.currentPhysicalLocation?.country || item.locationOfCreation?.country
  );

  if (rawCountry !== 'Unspecified') {
    const comboKey = `${cityKey}, ${rawCountry.toLowerCase()}`;
    if (MAP_LOOKUP[comboKey]) return comboKey;
  }

  return cityKey;
}

function getMapPointForItem(item: CatalogItem): MapPoint | null {
  const directCoordinates =
    item.currentPhysicalLocation?.coordinates || item.locationOfCreation?.coordinates;

  if (directCoordinates?.latitude != null && directCoordinates?.longitude != null) {
    return {
      label: getLocationLabel(item),
      value: 1,
      lat: directCoordinates.latitude,
      lng: directCoordinates.longitude
    };
  }

  const cityPart = getLookupCity(item);
  const mapped = MAP_LOOKUP[cityPart];

  if (!mapped) {
    return null;
  }

  return {
    label: getLocationLabel(item),
    value: 1,
    lat: mapped.lat,
    lng: mapped.lng
  };
}

function combineMapPoints(items: CatalogItem[]): MapPoint[] {
  const bucket = new Map<string, MapPoint>();

  items.forEach((item) => {
    const point = getMapPointForItem(item);
    if (!point) {
      return;
    }

    const key = `${point.label}-${point.lat.toFixed(3)}-${point.lng.toFixed(3)}`;
    const existing = bucket.get(key);

    if (existing) {
      existing.value += 1;
      return;
    }

    bucket.set(key, point);
  });

  return Array.from(bucket.values()).sort((a, b) => b.value - a.value).slice(0, 24);
}

function FitMapToPoints({ points }: { points: MapPoint[] }) {
  const map = useMap();

  useEffect(() => {
    if (points.length === 0) {
      map.setView([20, 0], 2);
      return;
    }

    if (points.length === 1) {
      map.setView([points[0].lat, points[0].lng], 5);
      return;
    }

    const bounds = latLngBounds(points.map((point) => [point.lat, point.lng]));
    map.fitBounds(bounds, { padding: [32, 32] });
  }, [map, points]);

  return null;
}

